import{_ as e,o as r,c as o,a2 as i}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"routex/getting-started/overview.md","filePath":"routex/getting-started/overview.md","lastUpdated":null}'),a={name:"routex/getting-started/overview.md"};function d(n,t,s,l,c,h){return r(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><p>RouteX is a high-performance TCP/UDP reverse proxy designed for production infrastructure handling thousands of concurrent connections. It combines kernel-level iptables rate limiting with an in-process L7 protection engine.</p><h2 id="design-philosophy" tabindex="-1">Design Philosophy <a class="header-anchor" href="#design-philosophy" aria-label="Permalink to &quot;Design Philosophy&quot;">​</a></h2><ul><li><strong>Isolation</strong>: Each proxy config is independent. One config failing validation never affects others.</li><li><strong>Defense in Depth</strong>: L3/L4 kernel rules catch volumetric attacks. L7 Go engine catches application-layer abuse.</li><li><strong>API-First</strong>: Everything is manageable via REST API. No config file editing required for runtime changes.</li><li><strong>Observability</strong>: Multi-format metrics, structured logging, per-connection access logs.</li></ul><h2 id="protocol-support" tabindex="-1">Protocol Support <a class="header-anchor" href="#protocol-support" aria-label="Permalink to &quot;Protocol Support&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Protocol</th><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td>TCP</td><td>Full proxy</td><td>Bidirectional streaming, connection tracking</td></tr><tr><td>UDP</td><td>Session-based</td><td>Per-client session affinity, idle timeout</td></tr><tr><td>TCP+UDP</td><td>Dual</td><td>Both protocols on the same port range</td></tr></tbody></table><h2 id="security-layers" tabindex="-1">Security Layers <a class="header-anchor" href="#security-layers" aria-label="Permalink to &quot;Security Layers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Mechanism</th><th>Scope</th></tr></thead><tbody><tr><td>1</td><td>Global ACL</td><td>Block/allowed CIDRs before any proxy</td></tr><tr><td>2</td><td>Per-Proxy ACL</td><td>Fine-grained per-service rules</td></tr><tr><td>3</td><td>iptables Rate Limiting</td><td>PPS, SYN flood, RST flood, connlimit</td></tr><tr><td>4</td><td>L7 Payload Inspection</td><td>Protocol validation for game traffic</td></tr><tr><td>5</td><td>Behavioral Scoring</td><td>Per-IP threat scoring → auto-ban</td></tr><tr><td>6</td><td>Connection Cycling Detection</td><td>Rapid open/close abuse</td></tr><tr><td>7</td><td>Payload Rate Limiting</td><td>Per-IP byte rate enforcement</td></tr><tr><td>8</td><td>Bandwidth Quotas</td><td>Hourly/daily/weekly/monthly limits</td></tr></tbody></table>',8)])])}const g=e(a,[["render",d]]);export{u as __pageData,g as default};
